#nullable enable // autogenerated

using MVZ2.GameContent.Entities;
using MVZ2.Vanilla.Enemies;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Entities;
using PVZEngine;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Enemies
{
    /// <summary>
    /// 伴舞僵尸。
    /// 它只做一件事：记住“自己的队长是谁”和“自己站在队长的哪个位置”，
    /// 然后靠这两个信息判断要不要等队长。
    /// （真正操控它走路的逻辑在别的文件里。）
    /// </summary>
    [AutoEntityBehaviourDefinition(VanillaEnemyNames.backupDancer)]
    public class BackupDancer : AIEntityBehaviour
    {
        // 构造函数：引擎创建这个行为时调用，名字交给父类就行。
        public BackupDancer(string nsp, string name) : base(nsp, name)
        {
        }

        /// <summary>
        /// 绑定关系：由舞王召唤时调用。
        /// 告诉这个伴舞：你的队长是谁、你要站在哪个偏移位置。
        /// </summary>
        public static void Setup(Entity entity, EntityID? leader, float offsetX)
        {
            entity.SetBehaviourField(ID, PROP_LEADER, leader);      // 记下队长 ID
            entity.SetBehaviourField(ID, PROP_OFFSET_X, offsetX);   // 记下自己的槽位偏移
            entity.SetBehaviourField(ID, PROP_BASE_SPEED, entity.GetSpeed(true)); // 记下原始速度
        }

        /// <summary>
        /// 取出出场时的原始速度（算队伍速度、判断是否按原速走时要用）。
        /// </summary>
        public static float GetBaseSpeed(Entity entity)
        {
            return entity.GetBehaviourField<float>(ID, PROP_BASE_SPEED);
        }

        /// <summary>
        /// 改写伴舞的“原始速度”（召唤时由舞王调用，让它和舞王速度一致）。
        /// </summary>
        public static void SetBaseSpeed(Entity entity, float value)
        {
            entity.SetBehaviourField(ID, PROP_BASE_SPEED, value);
        }

        /// <summary>
        /// 解除绑定：忘掉队长，从此像普通僵尸一样走。
        /// </summary>
        public static void ClearLeader(Entity entity)
        {
            entity.SetBehaviourField<EntityID>(ID, PROP_LEADER, null); // 存 null = 没有队长
        }

        /// <summary>
        /// 取出当前队长的 ID（可能为 null，表示已经没有队长）。
        /// </summary>
        public static EntityID? GetLeader(Entity entity)
        {
            return entity.GetBehaviourField<EntityID>(ID, PROP_LEADER);
        }

        /// <summary>
        /// 取出自己的槽位偏移（站在队长前/后/上/下的哪个位置）。
        /// </summary>
        public static float GetOffsetX(Entity entity)
        {
            return entity.GetBehaviourField<float>(ID, PROP_OFFSET_X);
        }

        /// <summary>
        /// 判断现在要不要停下等队长。
        /// 规则：如果自己已经跑到槽位前面去了，就返回 true（该等）。
        /// 没有队长、或队长已经死了，就不用等，返回 false。
        /// </summary>
        public static bool ShouldWaitForLeader(Entity entity)
        {
            // 用 ID 找到队长实体；?. 表示没 ID 时跳过，不会报错
            var leader = GetLeader(entity)?.GetEntity(entity.Level);
            // 没有队长，或队长已经死了 → 不需要等
            if (leader == null || !leader.ExistsAndAlive())
                return false;
            // 交给舞王那边的判断方法：自己是否超前于槽位
            return DancingZombie.IsAheadOfSlot(entity, leader, GetOffsetX(entity));
        }

        // 这个敌人的唯一 ID
        public static readonly NamespaceID ID = VanillaEnemyID.backupDancer;

        // 行为字段（相当于给伴舞准备的小抽屉）：
        //   leader     = 队长 ID
        //   offset_x   = 槽位偏移
        //   base_speed = 原始速度
        public static readonly VanillaEntityPropertyMeta<EntityID> PROP_LEADER = new VanillaEntityPropertyMeta<EntityID>("leader");
        public static readonly VanillaEntityPropertyMeta<float> PROP_OFFSET_X = new VanillaEntityPropertyMeta<float>("offset_x");
        public static readonly VanillaEntityPropertyMeta<float> PROP_BASE_SPEED = new VanillaEntityPropertyMeta<float>("base_speed");
    }
}
